CREATE OR REPLACE FUNCTION public.crm_create_lead(_input jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE cid uuid; lid uuid; own uuid:=(_input->>'ownerId')::uuid; BEGIN IF public.crm_role() IS NULL OR public.crm_role()='support' OR NOT public.crm_can_access(own) THEN RAISE EXCEPTION 'Denied'; END IF; INSERT INTO public.crm_customers(full_name,email,phone,company,acknowledgement,owner_id) VALUES(_input->>'fullName',COALESCE(_input->>'email',''),COALESCE(_input->>'phone',''),COALESCE(_input->>'company',''),NULLIF(_input->>'acknowledgement',''),own) RETURNING id INTO cid; INSERT INTO public.crm_leads(customer_id,title,amount,owner_id,next_follow_up) VALUES(cid,_input->>'title',COALESCE((_input->>'amount')::numeric,0),own,NULLIF(_input->>'followUp','')::date) RETURNING id INTO lid; RETURN lid; END $$;
REVOKE ALL ON FUNCTION public.crm_create_lead(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_create_lead(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.crm_onboard_member(_user_id uuid,_input jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE manager uuid:=NULLIF(_input->>'managerId','')::uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_user_id AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Verified account required'; END IF; IF manager IS NOT NULL AND (manager=_user_id OR NOT EXISTS(SELECT 1 FROM public.crm_memberships WHERE user_id=manager AND active AND role='BDM')) THEN RAISE EXCEPTION 'Invalid manager'; END IF; INSERT INTO public.crm_memberships(user_id,role,manager_id,active) VALUES(_user_id,_input->>'role',CASE WHEN _input->>'role'='BDM' THEN NULL ELSE manager END,(_input->>'active')::boolean) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,manager_id=excluded.manager_id,active=excluded.active; INSERT INTO public.crm_employee_profiles(user_id,employee_code,full_name,phone,designation,photo_url,joining_date) VALUES(_user_id,_input->>'employeeCode',_input->>'fullName',COALESCE(_input->>'phone',''),_input->>'designation',NULLIF(_input->>'photoUrl',''),(_input->>'joiningDate')::date) ON CONFLICT(user_id) DO UPDATE SET employee_code=excluded.employee_code,full_name=excluded.full_name,phone=excluded.phone,designation=excluded.designation,photo_url=excluded.photo_url,joining_date=excluded.joining_date; END $$;
REVOKE ALL ON FUNCTION public.crm_onboard_member(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_onboard_member(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.crm_customer_lookup(_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; role_name text:=public.crm_role(); BEGIN IF role_name IS NULL OR length(trim(_reference))<6 THEN RAISE EXCEPTION 'Denied'; END IF; SELECT jsonb_agg(jsonb_build_object('id',c.id,'customer_code',c.customer_code,'full_name',c.full_name,'email',c.email,'phone',c.phone,'company',c.company,'acknowledgement',c.acknowledgement)) INTO result FROM public.crm_customers c WHERE (c.customer_code=trim(_reference) OR c.acknowledgement=trim(_reference)) AND (role_name IN ('admin','support') OR public.crm_can_access(c.owner_id)); IF result IS NULL AND role_name IN ('admin','support') THEN SELECT jsonb_agg(jsonb_build_object('acknowledgement',ack_number,'full_name',student_name,'payment_status',payment_status,'approval_status',approval_status)) INTO result FROM public.education_support_registrations WHERE ack_number=trim(_reference); END IF; RETURN COALESCE(result,'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.crm_customer_lookup(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_customer_lookup(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.crm_import_submission(_kind text,_id uuid,_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c uuid; n text; e text; p text; title text; ack text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; IF EXISTS(SELECT 1 FROM public.crm_leads WHERE source=_kind AND source_id=_id) THEN RETURN; END IF; IF _kind='enquiry' THEN SELECT name,email,phone,service INTO n,e,p,title FROM public.contact_submissions WHERE id=_id; ELSIF _kind='education' THEN SELECT student_name,email,mobile,ack_number INTO n,e,p,ack FROM public.education_support_registrations WHERE id=_id; title:='Education Support'; ELSE RAISE EXCEPTION 'Unsupported source'; END IF; IF n IS NULL THEN RAISE EXCEPTION 'Not found'; END IF; INSERT INTO public.crm_customers(full_name,email,phone,acknowledgement,owner_id) VALUES(n,e,p,ack,_owner) RETURNING id INTO c; INSERT INTO public.crm_leads(customer_id,title,source,source_id,owner_id) VALUES(c,title,_kind,_id,_owner); END $$;
REVOKE ALL ON FUNCTION public.crm_import_submission(text,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_import_submission(text,uuid,uuid) TO authenticated;